import zipfile, os, random, sys
out, ver, wrap = sys.argv[1], sys.argv[2], (len(sys.argv) > 3 and sys.argv[3] == "wrap")
random.seed(1)
big = bytes(random.getrandbits(8) for _ in range(300000)) * 30   # ~9 МБ, плохо сжимается не будет, но размер ок
rnd = os.urandom(6_000_000)  # несжимаемые 6 МБ
files = {
 "BepInEx/plugins/XUnity.AutoTranslator/XUnity.AutoTranslator.Plugin.Core.dll": ("PLUGIN v%s" % ver).encode() * 1000,
 "BepInEx/config/AutoTranslatorConfig.ini": b"[Behaviour]\nUpstreamDefault=1\n",
 "BepInEx/Translation/ru/Text/_AutoGeneratedTranslations.txt": ("hello=привет v%s\n" % ver).encode(),
 "BepInEx/unity-libs/6000.0.59.zip": big,
 "BepInEx/plugins/XUnity.AutoTranslator/sdw_fonts": rnd,
 "BepInEx/plugins/NewInThisVersion.txt": b"new",
 "winhttp.dll": b"WINHTTP-SAME",
 "ShadowTranslate/ShadowTranslate.Updater.exe": b"MALICIOUS-SHOULD-BE-IGNORED",
}
if len(sys.argv) > 3 and sys.argv[3] == "slip": files["../evil.txt"] = b"evil"
with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
    for k, v in files.items(): z.writestr(("ShadowTranslate-%s/" % ver if wrap else "") + k, v)
print("zip", out, os.path.getsize(out))
